class GameServer {
    SOCKET sock;
    sockaddr_in serverAddr;
    std::unordered_map<int, PlayerState> players;
    std::unordered_map<std::string, int> addressToId;
    int nextPlayerId = 1;

public:
    GameServer(int port) {
#ifdef _WIN32
        WSADATA wsaData;
        WSAStartup(MAKEWORD(2, 2), &wsaData);
#endif
        sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);

        serverAddr.sin_family = AF_INET;
        serverAddr.sin_port = htons(port);
        serverAddr.sin_addr.s_addr = INADDR_ANY;

        bind(sock, (sockaddr*)&serverAddr, sizeof(serverAddr));

        // Set non-blocking
        u_long mode = 1;
        ioctlsocket(sock, FIONBIO, &mode);

        std::cout << "Server started on port " << port << "\n";
    }

    void run() {
        char buffer[1024];
        sockaddr_in clientAddr;
        int addrLen = sizeof(clientAddr);

        while (true) {
            int bytesRead = recvfrom(sock, buffer, sizeof(buffer), 0,
                                     (sockaddr*)&clientAddr, &addrLen);

            if (bytesRead > 0) {
                std::string clientKey = std::to_string(clientAddr.sin_addr.s_addr)
                                      + ":" + std::to_string(ntohs(clientAddr.sin_port));

                // Handle connection
                if (buffer[0] == 'C') {  // Connect message
                    int id = nextPlayerId++;
                    addressToId[clientKey] = id;
                    players[id] = {id, 0, 0, 0, 100, 30, 0};

                    // Send player ID back
                    sendto(sock, (char*)&id, sizeof(id), 0,
                           (sockaddr*)&clientAddr, addrLen);
                    std::cout << "Player " << id << " connected!\n";
                    continue;
                }

                // Handle input
                if (buffer[0] == 'I' && bytesRead >= sizeof(PlayerInput) + 1) {
                    PlayerInput input;
                    memcpy(&input, buffer + 1, sizeof(PlayerInput));

                    processInput(input);
                }
            }

            // Broadcast game state to all players
            broadcastState();

            std::this_thread::sleep_for(std::chrono::milliseconds(16));
        }
    }

    void processInput(const PlayerInput& input) {
        auto& player = players[input.playerId];
        float speed = 5.0f / 60.0f;

        if (input.w) player.z -= speed;
        if (input.s) player.z += speed;
        if (input.a) player.x -= speed;
        if (input.d) player.x += speed;

        if (input.shoot && player.ammo > 0) {
            player.ammo--;
