        }
    }

    void broadcastState() {
        for (auto& [id, state] : players) {
            // Send state to every player
            // Real implementation would send to each address
        }
    }

    ~GameServer() {
        closesocket(sock);
#ifdef _WIN32
        WSACleanup();
#endif
    }
};

int main() {
    GameServer server(7777);
    server.run();
    return 0;
}

