void onServerStateUpdate(ServerState state) {
    // Server position is the truth
    lastServerPosition = state.playerPosition;

    // Remove all inputs the server has processed
    while (!pendingInputs.empty() && 
           pendingInputs[0].sequenceNum <= state.lastProcessedSequence) {
        pendingInputs.erase(pendingInputs.begin());
    }

    // Re-apply all pending inputs on top of server state
    localPlayer.position = lastServerPosition;
    for (auto& input : pendingInputs) {
        localPlayer.position += calculateMovement(input, input.deltaTime);
    }
}

