struct Chunk {
    int x, z;
    bool loaded = false;
    float* heightMap = nullptr;  // terrain data
    int* objectIds = nullptr;     // trees, rocks, buildings

    Chunk(int cx, int cz) : x(cx), z(cz) {}

    void load() {
        if (loaded) return;
        std::cout << "Loading chunk (" << x << ", " << z << ")...\n";
        // Read from disk or generate
        heightMap = new float[256];
        objectIds = new int[64];
        loaded = true;
    }

    void unload() {
        if (!loaded) return;
        std::cout << "Unloading chunk (" << x << ", " << z << ")...\n";
        delete[] heightMap;
        delete[] objectIds;
        loaded = false;
    }

    ~Chunk() { unload(); }
};

class WorldStreamer {
    std::unordered_map<int, std::unique_ptr<Chunk>> chunks;
    int viewDistance = 4;  // Load 4 chunks in each direction
    int chunkSize = 64;     // Meters per chunk
    int lastChunkX = 999999, lastChunkZ = 999999;

    int getChunkKey(int x, int z) { return x * 100000 + z; }

public:
    void update(float playerX, float playerZ) {
        int currentChunkX = (int)(playerX / chunkSize);
        int currentChunkZ = (int)(playerZ / chunkSize);

        // Only update when player moves to a new chunk
        if (currentChunkX == lastChunkX && currentChunkZ == lastChunkZ) return;
        lastChunkX = currentChunkX;
        lastChunkZ = currentChunkZ;

        // Mark all chunks for potential unload
        std::unordered_map<int, bool> shouldKeep;

        // Load chunks in view distance
        for (int dx = -viewDistance; dx <= viewDistance; ++dx) {
            for (int dz = -viewDistance; dz <= viewDistance; ++dz) {
                int cx = currentChunkX + dx;
                int cz = currentChunkZ + dz;
                int key = getChunkKey(cx, cz);
                shouldKeep[key] = true;

                if (!chunks.count(key)) {
                    chunks[key] = std::make_unique<Chunk>(cx, cz);
                    chunks[key]->load();
                }
            }
        }

        // Unload chunks outside view distance
        auto it = chunks.begin();
        while (it != chunks.end()) {
            if (!shouldKeep.count(it->first)) {
                it->second->unload();
                it = chunks.erase(it);
            } else ++it;
        }

        std::cout << "Active chunks: " << chunks.size() << "\n";
    }
};

int main() {
    WorldStreamer streamer;

    // Simulate player moving through the world
    for (int i = 0; i < 5; ++i) {
        float x = i * 70.0f;  // Move 70 meters each step
        float z = 0;
        std::cout << "\nPlayer at (" << x << ", " << z << ")\n";
        streamer.update(x, z);
    }

    return 0;
}

