struct Weapon {
    float damage = 25.0f;
    float fireRate = 0.1f;        // seconds between shots
    float reloadTime = 1.5f;
    int maxAmmo = 30;
    int currentAmmo = 30;
    bool isAutomatic = true;
    float recoilAmount = 2.5f;
    float maxSpread = 0.1f;
    float spreadRecoveryRate = 10.0f;
    float currentSpread = 0.0f;
    float damageFalloffStart = 1000.0f;
    float damageFalloffEnd = 5000.0f;
    float range = 10000.0f;

    // Recoil pattern (advanced - cod-style)
    // Each shot adds to a pattern offset
    int shotsFired = 0;
    float recoilPatternX[30] = {
        0, 0, 0, 0, -0.5f, -0.8f, -0.5f, 0, 0.5f, 0.8f,
        0.5f, 0, -0.5f, -0.8f, -0.5f, 0, 0.5f, 1.0f, 0.5f, 0,
        -0.3f, -0.6f, -0.3f, 0, 0.3f, 0.6f, 0.3f, 0, -0.2f, 0
    };
    float recoilPatternY[30] = {
        1, 1.5f, 1.8f, 2.0f, 2.2f, 2.5f, 2.3f, 2.0f, 2.2f, 2.5f,
        2.3f, 2.0f, 2.2f, 2.5f, 2.3f, 2.0f, 2.2f, 2.5f, 2.0f, 1.8f,
        1.5f, 1.8f, 2.0f, 1.5f, 1.8f, 2.0f, 1.5f, 1.3f, 1.0f, 1.5f
    };

    bool fire() {
        if (currentAmmo <= 0 || fireTimer > 0) return false;

        currentAmmo--;
        shotsFired++;
        fireTimer = fireRate;

        // Increase spread
        currentSpread = std::min(currentSpread + 0.02f, maxSpread);

        return true;
    }

    void update(float dt) {
        fireTimer = std::max(0.0f, fireTimer - dt);
        currentSpread = std::max(0.0f, currentSpread - spreadRecoveryRate * dt);

        if (fireTimer <= 0) shotsFired = 0;  // Reset recoil pattern
    }

    Vector2 getRecoilOffset() const {
        if (shotsFired <= 0) return {0, 0};
        int idx = std::min(shotsFired - 1, 29);
        return {recoilPatternX[idx], recoilPatternY[idx]};
    }

    float fireTimer = 0;
};

struct RaycastHit {
    bool hit;
    float distance;
    Vector3 point;
    Vector3 normal;
    Entity* hitEntity;
    bool isHeadshot;
};

class ShootingSystem {
    std::mt19937 rng{std::random_device{}()};

public:
    RaycastHit shoot(const Weapon& weapon, const Vector3& origin, const Vector3& direction) {
        // Apply spread
        std::normal_distribution<float> spreadDist(0, weapon.currentSpread);
        float spreadX = spreadDist(rng);
        float spreadY = spreadDist(rng);

        Vector3 shotDir = direction;
        shotDir.x += spreadX;
        shotDir.y += spreadY;
        shotDir = shotDir.normalize();

        // Raycast (simplified - real engine does this against collision)
        RaycastHit hit;
        hit.hit = raycast(origin, origin + shotDir * weapon.range, hit);

        if (hit.hit) {
            // Damage falloff
            float damage = weapon.damage;
            if (hit.distance > weapon.damageFalloffStart) {
                float t = (hit.distance - weapon.damageFalloffStart) /
                          (weapon.damageFalloffEnd - weapon.damageFalloffStart);
                t = std::clamp(t, 0.0f, 1.0f);
                damage *= (1.0f - t * 0.5f);  // 50% damage at max range
            }

            // Headshot multiplier
            if (hit.isHeadshot) damage *= 2.0f;

            // Apply damage to hit entity
            if (hit.hitEntity) hit.hitEntity->takeDamage(damage);
        }

        return hit;
    }
};
